#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];E=R/'docs/urinary-release';v=json.loads((E/'final/verification.json').read_text());assert v['ok'] and len(v['cases'])==180 and len(v['initialPages'])==20
slugs=list(dict.fromkeys(x['slug']for x in v['initialPages']));short=['腎臟構造','腎元與血流','過濾與清除','腎小管處理','尿液濃縮','尿路與排尿','體液分布','鈉水調節','電解質平衡','酸鹼調節'];data=[]
for i,slug in enumerate(slugs):
 c=json.loads((R/f'materials-src/{slug}/content.json').read_text());images={'1280':{},'390':{}}
 for x in v['initialPages']+v['cases']:
  if x['slug']!=slug:continue
  key=x['slot']+('-'+x['state']if x.get('state')else'')if 'slot'in x else'initial';images[str(x['width'])][key]='final/'+x['screenshot']
 assert all(len(x)==10 for x in images.values())
 labels={'initial':'初始完整頁'};labels.update({'overview-'+s['id']:s['label']for s in c['lab']['states']});labels.update({f'node-{j+1:02d}':n['title']for j,n in enumerate(c['nodes'])})
 data.append(dict(slug=slug,title=c['title'],short=short[i],kind='泌尿'if i<6 else'體液',preview=f'../../public/materials/{slug}-{c["version"]}/index.html',images=images,labels=labels))
html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>泌尿與體液｜十份畫面並列</title>
<style>
:root{font:15px/1.6 -apple-system,BlinkMacSystemFont,"PingFang TC",sans-serif;color:#172c3c;background:#f3f6f9}*{box-sizing:border-box}body{margin:0}header{padding:25px 24px 18px;background:#102d42;color:white}header small{letter-spacing:.12em;color:#a8c8dc}h1{font-size:27px;line-height:1.4;margin:5px 0 8px}header p{margin:0;color:#d5e4ee}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:14px 24px;background:white;border-bottom:1px solid #cfdae3;position:sticky;top:0;z-index:2}label{display:flex;align-items:center;gap:7px}select,button{font:inherit;border:1px solid #b8c9d5;border-radius:7px;background:white;color:#18384c;padding:7px 10px}button{cursor:pointer}button:hover{border-color:#0072b2;background:#eef7fd}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #e69f00;outline-offset:3px}.status{margin-left:auto;color:#28654a;font-size:13px}.hint{margin:15px 24px 10px;color:#526b7e}.scroll{overflow-x:auto;padding:0 16px 30px}.grid{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:8px;align-items:start}.expanded .grid{min-width:2400px}.card{background:white;border:1px solid #d9e2e9;border-radius:10px;overflow:hidden;min-width:0}.cardhead{padding:11px 8px 9px;min-height:118px;border-top:4px solid #1b8886}.card.fluid .cardhead{border-top-color:#0072b2}.num{font-size:11px;letter-spacing:.08em;color:#668193}.card h2{font-size:14px;line-height:1.5;margin:5px 0;word-break:keep-all;overflow-wrap:anywhere}.card a{color:#00659c;font-size:12px;text-decoration:none}.card a:hover{text-decoration:underline}.shot{width:100%;padding:6px;border:0;border-radius:0;display:block;background:#fff;min-height:165px}.shot img{display:block;max-width:100%;height:auto;margin:auto}.caption{padding:9px 8px 12px;border-top:1px solid #edf1f5;font-size:12px;color:#4e6678;min-height:78px}.caption strong{display:block;color:#223e51}.footer{padding:0 24px 30px;color:#607789;font-size:13px}dialog{border:0;border-radius:14px;padding:0;max-width:96vw;width:1120px;max-height:94vh;box-shadow:0 15px 70px #0005}dialog::backdrop{background:#102536c9}.dialogbar{display:flex;gap:12px;align-items:center;position:sticky;top:0;background:white;padding:12px 16px;border-bottom:1px solid #d9e2e9}.dialogbar strong{flex:1}.dialogimage{padding:12px;overflow:auto}.dialogimage img{display:block;width:auto;max-width:100%;height:auto;margin:auto}@media(max-width:700px){header{padding:18px}h1{font-size:22px}.toolbar{padding:10px 16px;gap:8px}.status{margin-left:0;width:100%}.grid{min-width:1800px;gap:10px}.hint{margin-left:16px}.cardhead{min-height:110px}.shot{min-height:220px}}
</style>
<header><small>LOCAL PREVIEW · 2026-10-16</small><h1>泌尿 6 ＋ 體液 4｜畫面總覽</h1><p>十份並列比較；點圖放大，或開啟完整互動預覽。</p></header>
<div class="toolbar"><label>畫面寬度<select id="width"><option value="1280">桌機 1280 px</option><option value="390">手機 390 px</option></select></label><label>觀看內容<select id="view"><option value="initial">初始完整頁</option><option value="overview-state-1" selected>總覽狀態 1</option><option value="overview-state-2">總覽狀態 2</option><option value="overview-state-3">總覽狀態 3</option><option value="node-01">節點 01</option><option value="node-02">節點 02</option><option value="node-03">節點 03</option><option value="node-04">節點 04</option><option value="node-05">節點 05</option><option value="node-06">節點 06</option></select></label><button id="previous" aria-label="上一畫面">←</button><button id="next" aria-label="下一畫面">→</button><button id="expand" aria-pressed="false">加寬並列</button><span class="status">180 圖面檢查通過 · 200 張截圖</span></div>
<p class="hint">每份皆有初始頁、三個總覽狀態與六個節點，可切換兩種寬度。手機可橫向移動畫廊。</p><div class="scroll"><main class="grid" id="grid"></main></div><p class="footer">尿路節點 06 依交辦保留圖面佔位，文字內容與題目已完成。全部為本機預覽，待 Claude 總驗收。</p>
<dialog id="zoom"><div class="dialogbar"><strong id="zoomtitle"></strong><a id="original" target="_blank" rel="noreferrer">原尺寸圖片</a><button id="close">關閉 ×</button></div><div class="dialogimage"><img id="zoomimage" alt="放大的教材截圖"></div></dialog>
<script>const materials=__DATA__;const grid=document.getElementById('grid'),width=document.getElementById('width'),view=document.getElementById('view'),zoom=document.getElementById('zoom');
function render(){grid.replaceChildren();materials.forEach((m,i)=>{const card=document.createElement('article');card.className='card'+(m.kind==='體液'?' fluid':'');const head=document.createElement('div');head.className='cardhead';const num=document.createElement('div');num.className='num';num.textContent=String(i+1).padStart(2,'0')+' / '+m.kind;const h=document.createElement('h2');h.textContent=m.short;h.title=m.title;const link=document.createElement('a');link.href=m.preview;link.target='_blank';link.rel='noreferrer';link.textContent='完整預覽 ↗';head.append(num,h,link);const b=document.createElement('button');b.className='shot';b.setAttribute('aria-label','放大'+m.title);const img=document.createElement('img');img.src=m.images[width.value][view.value];img.alt=m.title+'｜'+m.labels[view.value];b.append(img);b.addEventListener('click',()=>{document.getElementById('zoomtitle').textContent=img.alt+' · '+width.value+' px';document.getElementById('zoomimage').src=img.src;document.getElementById('original').href=img.src;zoom.showModal();});const caption=document.createElement('div');caption.className='caption';const strong=document.createElement('strong');strong.textContent=m.labels[view.value];caption.append(strong,document.createTextNode(m.slug==='urinary-route-micturition'&&view.value==='node-06'?'本節圖待製作':'兩尺寸／全部圖面驗證通過'));card.append(head,b,caption);grid.append(card);});}
width.addEventListener('change',render);view.addEventListener('change',render);document.getElementById('close').addEventListener('click',()=>zoom.close());document.getElementById('expand').addEventListener('click',e=>{const on=document.body.classList.toggle('expanded');e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'全部置入畫面':'加寬並列';});function step(n){view.selectedIndex=(view.selectedIndex+n+view.options.length)%view.options.length;render();}document.getElementById('previous').onclick=()=>step(-1);document.getElementById('next').onclick=()=>step(1);document.addEventListener('keydown',e=>{if(!zoom.open&&e.key==='ArrowRight')step(1);if(!zoom.open&&e.key==='ArrowLeft')step(-1);});render();</script></html>'''
(E/'screenshots.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
print('Gallery created: ten parallel materials, all 200 screenshots indexed.')
